import{_ as s,a as r,o as t,a6 as a}from"./chunks/framework.CJDy2q7X.js";const l=JSON.parse('{"title":"Process GDPR Request (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-customer-gdpr-process-gql","title":"Process GDPR Request","description":"The GraphQL input uses requestId because id is reserved as the resource IRI on mutation inputs.","query":"mutation Process($input: createAdminCustomerGdprProcessInput!) {\\n  createAdminCustomerGdprProcess(input: $input) {\\n    adminCustomerGdprProcess {\\n      id\\n      _id\\n      requestId\\n      customerId\\n      type\\n      status\\n      customerDeleted\\n      processedAt\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"requestId\\": \\"9\\",\\n    \\"message\\": \\"Approved on customer request.\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCustomerGdprProcess\\": {\\n      \\"adminCustomerGdprProcess\\": {\\n        \\"id\\": \\"/api/admin/customers/gdpr-requests/9/process\\",\\n        \\"_id\\": 9,\\n        \\"requestId\\": 9,\\n        \\"customerId\\": 14,\\n        \\"type\\": \\"delete\\",\\n        \\"status\\": \\"approved\\",\\n        \\"customerDeleted\\": true,\\n        \\"processedAt\\": \\"2026-06-24 10:30:00\\",\\n        \\"message\\": \\"GDPR request processed successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/customers/gdpr/process.md","filePath":"api/graphql-api/admin/customers/gdpr/process.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/admin/customers/gdpr/process.md"};function d(n,e,p,u,i,c){return t(),r("div",null,e[0]||(e[0]=[a('<h1 id="process-gdpr-request-graphql" tabindex="-1">Process GDPR Request (GraphQL) <a class="header-anchor" href="#process-gdpr-request-graphql" aria-label="Permalink to &quot;Process GDPR Request (GraphQL)&quot;">​</a></h1><p>Approves and executes a GDPR request. For <code>type=delete</code> requests this cascades the customer deletion (<code>customerDeleted</code> reports whether it happened); for <code>type=update</code> it marks the request approved so the admin can apply the changes manually.</p><h3 id="destructive" tabindex="-1">Destructive <a class="header-anchor" href="#destructive" aria-label="Permalink to &quot;Destructive&quot;">​</a></h3><p>For delete requests this permanently removes the customer. Already-approved or revoked requests are refused (surfaced in <code>errors[]</code>).</p><h3 id="graphql-input-quirk" tabindex="-1">GraphQL input quirk <a class="header-anchor" href="#graphql-input-quirk" aria-label="Permalink to &quot;GraphQL input quirk&quot;">​</a></h3><p>The input uses <code>requestId</code> (not <code>id</code>) — <code>id</code> is reserved as the resource IRI on mutation inputs.</p><p>Permission: <code>customers.gdpr_requests.edit</code>.</p><p>See the <a href="/api/graphql-api/admin/customers/gdpr/">GDPR overview</a> for how requests are processed.</p>',8)]))}const h=s(o,[["render",d]]);export{l as __pageData,h as default};
